svg.script:

const svg = document.querySelector('svg');
const snake1Group = document.getElementById('snake1');
const snake2Group = document.getElementById('snake2');
const food = document.getElementById('food');
const scoreText = document.getElementById('score');
let snake1 = [{x: 10, y: 15}];
let snake2 = [{x: 75, y: 15}];
let foodPos = {x: 15, y: 15};
let foodType = 'fish-red';
let score = 0;
let gameInterval;

function drawSnake(snake, group, headClass, bodyClass) {
  group.innerHTML = '';
  snake.forEach((segment, index) => {
    const element = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
    element.setAttribute('x', segment.x);
    element.setAttribute('y', segment.y);
    element.setAttribute('width', 1);
    element.setAttribute('height', 1);
    element.setAttribute('rx', 0.2);
    element.setAttribute('class', index === 0 ? headClass : bodyClass);
    group.appendChild(element);
  });
}

function getNextMove(snake, target) {
  const head = snake[0];
  const dx = target.x - head.x;
  const dy = target.y - head.y;
  let direction = {x: 0, y: 0};

  if (Math.abs(dx) > Math.abs(dy)) {
    direction.x = dx > 0 ? 1 : -1;
  } else {
    direction.y = dy > 0 ? 1 : -1;
  }

  const nextHead = {x: head.x + direction.x, y: head.y + direction.y};
  if (snake.some(seg => seg.x === nextHead.x && seg.y === nextHead.y)) {
    direction = {x: 0, y: 0};
    if (Math.abs(dx) <= Math.abs(dy)) {
      direction.x = dx > 0 ? 1 : -1;
    } else {
      direction.y = dy > 0 ? 1 : -1;
    }
  }

  return direction;
}

function spawnFood() {
  const foodTypes = ['fish-red', 'fish-yellow', 'fish-blue', 'gold'];
  const probabilities = [0.3, 0.3, 0.2, 0.2]; // 20% chance for gold
  let rand = Math.random();
  let cumulative = 0;
  let selectedType = 'fish-red';
  for (let i = 0; i < probabilities.length; i++) {
    cumulative += probabilities[i];
    if (rand < cumulative) {
      selectedType = foodTypes[i];
      break;
    }
  }

  foodPos = {x: Math.floor(Math.random() * 85.4), y: Math.floor(Math.random() * 30)};
  while (snake1.some(seg => seg.x === foodPos.x && seg.y === foodPos.y) || snake2.some(seg => seg.x === foodPos.x && seg.y === foodPos.y)) {
    foodPos = {x: Math.floor(Math.random() * 85.4), y: Math.floor(Math.random() * 30)};
  }
  foodType = selectedType;
  food.setAttribute('x', foodPos.x);
  food.setAttribute('y', foodPos.y + 0.5);
  food.setAttribute('class', foodType);
  food.textContent = foodType === 'gold' ? '💰' : '🐟';
}

function moveSnakes() {
  // Move snake1
  let direction1 = getNextMove(snake1, foodPos);
  let head1 = {x: snake1[0].x + direction1.x, y: snake1[0].y + direction1.y};

  // Move snake2
  let direction2 = getNextMove(snake2, foodPos);
  let head2 = {x: snake2[0].x + direction2.x, y: snake2[0].y + direction2.y};

  // Check for collisions
  if (head1.x < 0 || head1.x >= 85.4 || head1.y < 0 || head1.y >= 30 || 
      snake1.some(seg => seg.x === head1.x && seg.y === head1.y) ||
      snake2.some(seg => seg.x === head1.x && seg.y === head1.y)) {
    clearInterval(gameInterval);
    alert('Game Over! Snake 1 crashed. Score: ' + score);
    return;
  }
  if (head2.x < 0 || head2.x >= 85.4 || head2.y < 0 || head2.y >= 30 || 
      snake2.some(seg => seg.x === head2.x && seg.y === head2.y) ||
      snake1.some(seg => seg.x === head2.x && seg.y === head2.y)) {
    clearInterval(gameInterval);
    alert('Game Over! Snake 2 crashed. Score: ' + score);
    return;
  }

  snake1.unshift(head1);
  snake2.unshift(head2);

  // Check for food
  let ateFood = false;
  if (Math.abs(head1.x - foodPos.x) < 0.5 && Math.abs(head1.y - foodPos.y) < 0.5) {
    score += foodType === 'gold' ? 5 : 1;
    scoreText.textContent = 'Score: ' + score;
    ateFood = true;
  } else if (Math.abs(head2.x - foodPos.x) < 0.5 && Math.abs(head2.y - foodPos.y) < 0.5) {
    score += foodType === 'gold' ? 5 : 1;
    scoreText.textContent = 'Score: ' + score;
    ateFood = true;
  }

  if (ateFood) {
    spawnFood();
  } else {
    snake1.pop();
    snake2.pop();
  }

  drawSnake(snake1, snake1Group, 'snake1-head', 'snake1-body');
  drawSnake(snake2, snake2Group, 'snake2-head', 'snake2-body');
}

spawnFood();
gameInterval = setInterval(moveSnakes, 150);
drawSnake(snake1, snake1Group, 'snake1-head', 'snake1-body');
drawSnake(snake2, snake2Group, 'snake2-head', 'snake2-body');
